package thmodern.boat;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraftforge.gametest.*;
import thmodern.Horizons;
@GameTestHolder(Horizons.ID) @PrefixGameTestTemplate(false)
public final class BoatServerTests {
 @GameTest(template="empty")
 public static void metalFloatsInLavaAndProtectsBothRiders(GameTestHelper test){var level=test.getLevel();var pos=test.absolutePos(new net.minecraft.core.BlockPos(2,2,2));for(var target:net.minecraft.core.BlockPos.betweenClosed(pos.offset(-1,0,-1),pos.offset(1,0,1)))level.setBlock(target,Blocks.LAVA.defaultBlockState(),3);var metal=Horizons.THAUMIUM_BOAT.get().create(level);var wood=Horizons.GREATWOOD_BOAT.get().create(level);metal.setPos(pos.getX()+.5,pos.getY()+.2,pos.getZ()+.5);wood.setPos(metal.position());level.addFreshEntity(metal);test.assertTrue(metal.canBoatInFluid(Blocks.LAVA.defaultBlockState().getFluidState())&&!wood.canBoatInFluid(Blocks.LAVA.defaultBlockState().getFluidState()),"Only metal boat uses lava buoyancy");var player=test.makeMockPlayer();var other=test.makeMockPlayer();test.assertTrue(player.startRiding(metal)&&other.startRiding(metal)&&!test.makeMockPlayer().startRiding(metal),"Two passengers use modern seating, a third cannot mount");player.setSecondsOnFire(10);other.setSecondsOnFire(10);metal.tick();test.assertTrue(!other.isOnFire()&&other.hasEffect(net.minecraft.world.effect.MobEffects.FIRE_RESISTANCE)&&!player.isOnFire()&&player.hasEffect(net.minecraft.world.effect.MobEffects.FIRE_RESISTANCE),"Metal boat extinguishes and protects its rider");test.assertTrue(!metal.causeFallDamage(40,1,level.damageSources().fall()),"Legacy boat does not break on falls");metal.discard();test.succeed();}
 @GameTest(template="empty")
 public static void breakingBoatReturnsCorrectItemOnce(GameTestHelper test){var level=test.getLevel();var pos=test.absolutePos(new net.minecraft.core.BlockPos(2,2,2));// Drops may lie above the empty structure bounds and survive a previous run.
var dropBounds=new net.minecraft.world.phys.AABB(pos).inflate(2);level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,dropBounds,e->e.getItem().is(Horizons.GREATWOOD_BOAT_ITEM.get())).forEach(net.minecraft.world.entity.Entity::discard);var boat=Horizons.GREATWOOD_BOAT.get().create(level);boat.setPos(pos.getX()+.5,pos.getY()+.5,pos.getZ()+.5);level.addFreshEntity(boat);boat.hurt(level.damageSources().generic(),4);test.assertTrue(boat.isAlive(),"Damage threshold is strictly greater than forty");boat.hurt(level.damageSources().generic(),1);test.assertTrue(!boat.isAlive(),"Fifth point destroys boat");boat.hurt(level.damageSources().generic(),1);var drops=level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(pos).inflate(2),e->e.getItem().is(Horizons.GREATWOOD_BOAT_ITEM.get()));test.assertTrue(drops.size()==1&&drops.get(0).getItem().getCount()==1,"Repeated hurt cannot duplicate boat return: "+drops.stream().map(e->e.getItem().toString()).toList());drops.forEach(net.minecraft.world.entity.Entity::discard);test.succeed();}
}
